import re
import sqlite3
from flask import Blueprint, Response, current_app, g, request
from warehouse import store

@api_bp.get("/stock/<sku>/history")
def stock_history(sku: str):
    """Latest changes for a SKU; ?limit= up to 100."""
    if bad := check_sku(sku):
        return bad
    try:
        limit = min(max(int(request.args.get("limit", "20")), 1), 100)
    except ValueError:
        return error("WH-VAL-422", "'limit' must be an integer", 422)
    return {"items": store.sync_history(db(), sku, limit)}

