import re
import sqlite3
from flask import Blueprint, Response, current_app, g, request
from warehouse import store

@api_bp.get("/stock/<sku>")
def get_stock(sku: str):
    """One SKU's stock level."""
    if bad := check_sku(sku):
        return bad
    level = store.get_level(db(), sku)
    return level if level else error("WH-STK-404", f"no stock record for {sku}", 404)

